(230,'gallery','Photo Gallery | Peshawar Medical College','Gallery','News','Photos of campus life, labs, and events at Peshawar Medical College, Peshawar.','gallery','<style>\r\n    /* ══ FILTER TABS ══ */\r\n    .gallery-filters {\r\n      display: flex;\r\n      flex-wrap: wrap;\r\n      gap: 10px;\r\n      margin-bottom: 40px;\r\n      justify-content: center;\r\n    }\r\n    .gf-btn {\r\n      font-family: var(--font-head);\r\n      font-size: .78rem;\r\n      font-weight: 700;\r\n      padding: 9px 22px;\r\n      border-radius: 100px;\r\n      border: 2px solid var(--border);\r\n      background: white;\r\n      color: var(--gray-dark);\r\n      cursor: pointer;\r\n      transition: all .2s;\r\n      letter-spacing: .02em;\r\n    }\r\n    .gf-btn:hover  { border-color: var(--teal); color: var(--teal); }\r\n    .gf-btn.active { background: var(--teal); border-color: var(--teal); color: white; }\r\n\r\n    /* ══ GALLERY GRID ══ */\r\n    .gallery-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 14px;\r\n    }\r\n    .gallery-item {\r\n      position: relative;\r\n      border-radius: var(--r-md);\r\n      overflow: hidden;\r\n      aspect-ratio: 1;\r\n      cursor: pointer;\r\n      background: var(--gray-light);\r\n      transition: transform .3s, box-shadow .3s;\r\n    }\r\n    .gallery-item:hover { transform: scale(1.02); box-shadow: var(--shadow-lg); }\r\n\r\n    /* Span variants */\r\n    .gallery-item.span-2     { grid-column: span 2; aspect-ratio: 2/1; }\r\n    .gallery-item.span-2-row { grid-row: span 2; aspect-ratio: 1/2; }\r\n\r\n    .gallery-img {\r\n      width: 100%; height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s;\r\n    }\r\n    .gallery-item:hover .gallery-img { transform: scale(1.06); }\r\n\r\n    /* Placeholder (when no image) */\r\n    .gallery-placeholder {\r\n      width: 100%; height: 100%;\r\n      background: linear-gradient(135deg, var(--navy), var(--navy-mid));\r\n      display: flex; flex-direction: column;\r\n      align-items: center; justify-content: center;\r\n      gap: 10px;\r\n      transition: filter .3s;\r\n    }\r\n    .gallery-placeholder i    { font-size: 2rem; color: rgba(255,255,255,.5); }\r\n    .gallery-placeholder span { font-family: var(--font-head); font-size: .75rem; color: rgba(255,255,255,.4); text-transform: uppercase; letter-spacing: .08em; }\r\n\r\n    /* Overlay */\r\n    .gallery-overlay {\r\n      position: absolute; inset: 0;\r\n      background: linear-gradient(to top, rgba(10,22,40,.85) 0%, transparent 55%);\r\n      opacity: 0;\r\n      transition: opacity .25s;\r\n      display: flex; align-items: flex-end;\r\n      padding: 18px;\r\n    }\r\n    .gallery-item:hover .gallery-overlay { opacity: 1; }\r\n    .gallery-overlay-text {\r\n      font-family: var(--font-head);\r\n      font-size: .82rem;\r\n      font-weight: 700;\r\n      color: white;\r\n      line-height: 1.3;\r\n    }\r\n    .gallery-overlay-cat {\r\n      font-family: var(--font-body);\r\n      font-size: .68rem;\r\n      font-weight: 700;\r\n      color: var(--teal-light);\r\n      text-transform: uppercase;\r\n      letter-spacing: .08em;\r\n      margin-bottom: 3px;\r\n    }\r\n    /* Zoom icon badge */\r\n    .gallery-zoom {\r\n      position: absolute;\r\n      top: 12px; right: 12px;\r\n      width: 32px; height: 32px;\r\n      background: rgba(255,255,255,.15);\r\n      backdrop-filter: blur(8px);\r\n      border-radius: 8px;\r\n      display: flex; align-items: center; justify-content: center;\r\n      color: white; font-size: .9rem;\r\n      opacity: 0; transition: opacity .25s;\r\n    }\r\n    .gallery-item:hover .gallery-zoom { opacity: 1; }\r\n\r\n    /* ══ LIGHTBOX ══ */\r\n    .pmc-lightbox {\r\n      position: fixed; inset: 0;\r\n      background: rgba(6,14,26,.96);\r\n      z-index: 9999;\r\n      display: none;\r\n      align-items: center;\r\n      justify-content: center;\r\n    }\r\n    .pmc-lightbox.open { display: flex; animation: lbFade .25s ease; }\r\n    @keyframes lbFade { from{opacity:0} to{opacity:1} }\r\n\r\n    .lb-inner {\r\n      position: relative;\r\n      max-width: 90vw;\r\n      max-height: 90vh;\r\n      display: flex;\r\n      flex-direction: column;\r\n      align-items: center;\r\n    }\r\n    .lb-img-wrap {\r\n      position: relative;\r\n      border-radius: var(--r-md);\r\n      overflow: hidden;\r\n      box-shadow: 0 24px 80px rgba(0,0,0,.6);\r\n    }\r\n    .lb-img {\r\n      max-width: 88vw;\r\n      max-height: 76vh;\r\n      object-fit: contain;\r\n      display: block;\r\n    }\r\n    /* Placeholder in lightbox */\r\n    .lb-placeholder {\r\n      width: 600px; max-width: 88vw;\r\n      height: 400px; max-height: 76vh;\r\n      background: linear-gradient(135deg, var(--navy), var(--navy-mid));\r\n      display: flex; flex-direction: column;\r\n      align-items: center; justify-content: center;\r\n      gap: 14px;\r\n    }\r\n    .lb-placeholder i    { font-size: 3rem; color: rgba(255,255,255,.4); }\r\n    .lb-placeholder span { font-family:var(--font-head); font-size:.8rem; color:rgba(255,255,255,.35); }\r\n\r\n    .lb-caption {\r\n      margin-top: 16px;\r\n      text-align: center;\r\n    }\r\n    .lb-caption-title {\r\n      font-family: var(--font-head);\r\n      font-size: .95rem;\r\n      font-weight: 700;\r\n      color: white;\r\n      margin-bottom: 3px;\r\n    }\r\n    .lb-caption-cat {\r\n      font-family: var(--font-body);\r\n      font-size: .75rem;\r\n      color: var(--teal-light);\r\n      font-weight: 600;\r\n      text-transform: uppercase;\r\n      letter-spacing: .07em;\r\n    }\r\n    .lb-counter {\r\n      font-family: var(--font-body);\r\n      font-size: .75rem;\r\n      color: rgba(255,255,255,.35);\r\n      margin-top: 6px;\r\n    }\r\n\r\n    /* Controls */\r\n    .lb-close {\r\n      position: absolute;\r\n      top: -48px; right: 0;\r\n      width: 40px; height: 40px;\r\n      background: rgba(255,255,255,.1);\r\n      border: none; border-radius: 8px;\r\n      color: white; font-size: 1.1rem;\r\n      cursor: pointer;\r\n      display: flex; align-items: center; justify-content: center;\r\n      transition: background .2s;\r\n    }\r\n    .lb-close:hover { background: rgba(255,255,255,.2); }\r\n\r\n    .lb-prev, .lb-next {\r\n      position: fixed;\r\n      top: 50%; transform: translateY(-50%);\r\n      width: 48px; height: 48px;\r\n      background: rgba(255,255,255,.1);\r\n      border: 1px solid rgba(255,255,255,.15);\r\n      border-radius: 50%;\r\n      color: white; font-size: 1.2rem;\r\n      cursor: pointer;\r\n      display: flex; align-items: center; justify-content: center;\r\n      transition: background .2s;\r\n    }\r\n    .lb-prev { left: 20px; }\r\n    .lb-next { right: 20px; }\r\n    .lb-prev:hover, .lb-next:hover { background: rgba(21,95,122,.5); }\r\n\r\n    /* ══ ALBUM SECTION HEADING ══ */\r\n    .album-heading {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 14px;\r\n      margin-bottom: 22px;\r\n      padding-bottom: 14px;\r\n      border-bottom: 2px solid var(--border);\r\n    }\r\n    .album-heading-icon {\r\n      width: 44px; height: 44px;\r\n      background: var(--navy);\r\n      border-radius: 10px;\r\n      display: flex; align-items: center; justify-content: center;\r\n      color: var(--gold); font-size: 1.2rem;\r\n      flex-shrink: 0;\r\n    }\r\n    .album-title {\r\n      font-family: var(--font-head);\r\n      font-size: 1.1rem;\r\n      font-weight: 800;\r\n      color: var(--navy);\r\n    }\r\n    .album-count {\r\n      font-family: var(--font-body);\r\n      font-size: .75rem;\r\n      font-weight: 700;\r\n      color: white;\r\n      background: var(--teal);\r\n      padding: 2px 10px;\r\n      border-radius: 100px;\r\n    }\r\n\r\n    /* ══ EMPTY STATE ══ */\r\n    .gallery-empty {\r\n      text-align: center;\r\n      padding: 70px 0;\r\n    }\r\n    .gallery-empty i { font-size: 3rem; color: var(--gray-light); margin-bottom: 14px; display: block; }\r\n\r\n    /* ══ BACK TO TOP ══ */\r\n    #backToTop {\r\n      position: fixed; bottom: 28px; right: 28px;\r\n      width: 44px; height: 44px; background: var(--teal);\r\n      color: white; border: none; border-radius: 10px; font-size: 1.1rem;\r\n      display: flex; align-items: center; justify-content: center;\r\n      cursor: pointer; z-index: 999; opacity: 0; transform: translateY(10px);\r\n      transition: opacity .25s, transform .25s, background .2s;\r\n      box-shadow: 0 4px 18px rgba(21,95,122,.35);\r\n    }\r\n    #backToTop.visible { opacity: 1; transform: translateY(0); }\r\n    #backToTop:hover   { background: var(--navy); }\r\n\r\n    /* ══ RESPONSIVE ══ */\r\n    @media (max-width: 991.98px) {\r\n      .gallery-grid { grid-template-columns: repeat(3,1fr); }\r\n      .gallery-item.span-2 { grid-column: span 2; }\r\n      .gallery-item.span-2-row { grid-row: span 1; aspect-ratio: 1; }\r\n    }\r\n    @media (max-width: 767.98px) {\r\n      .gallery-grid { grid-template-columns: repeat(2,1fr); }\r\n      .gallery-item.span-2     { grid-column: span 2; }\r\n      .gallery-item.span-2-row { grid-row: span 1; aspect-ratio: 1; }\r\n      .lb-prev, .lb-next { display: none; }\r\n    }\r\n    @media (max-width: 480px) {\r\n      .gallery-grid { grid-template-columns: 1fr 1fr; gap: 8px; }\r\n    }\r\n  </style>\r\n\r\n\r\n\r\n\r\n<!-- ═══ PAGE HERO ═══ -->\r\n<div class=\"page-hero\">\r\n  <div class=\"page-hero-grid\"></div>\r\n  <div class=\"container page-hero-content\">\r\n    <h1>Photo Gallery</h1>\r\n    <div class=\"breadcrumb-pmc\">\r\n      <a href=\"/\">Home</a>\r\n      <span class=\"sep\"><i class=\"bi bi-chevron-right\"></i></span>\r\n      <span class=\"current\">Gallery</span>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- ═══ GALLERY CONTENT ═══ -->\r\n<section class=\"pmc-section bg-off\">\r\n  <div class=\"container\">\r\n\r\n    <!-- Intro -->\r\n    <div class=\"row m